const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const covers={Fantasy:'https://images.unsplash.com/photo-1518709268805-4e9042af9f23?auto=format&fit=crop&w=900&q=80',Mystery:'https://images.unsplash.com/photo-1519608487953-e999c86e7455?auto=format&fit=crop&w=900&q=80',Romance:'https://images.unsplash.com/photo-1516589178581-6cd7833ae3b2?auto=format&fit=crop&w=900&q=80',Thriller:'https://images.unsplash.com/photo-1511497584788-876760111969?auto=format&fit=crop&w=900&q=80','Science fiction':'https://images.unsplash.com/photo-1451187580459-43490279c0fa?auto=format&fit=crop&w=900&q=80',Horror:'https://images.unsplash.com/photo-1509248961158-e54f6934749c?auto=format&fit=crop&w=900&q=80',Original:'https://images.unsplash.com/photo-1478720568477-152d9b164e26?auto=format&fit=crop&w=900&q=80',Adventure:'https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=900&q=80',Comedy:'https://images.unsplash.com/photo-1492684223066-81342ee5ff30?auto=format&fit=crop&w=900&q=80'};
const initialStories=[{id:'p1',title:'The Secret Garden',genre:'Fantasy',source:'Public domain · Frances Hodgson Burnett',text:'When Mary Lennox was sent to Misselthwaite Manor to live with her uncle, everybody said she was the most disagreeable-looking child ever seen. It was true, too. She had a little thin face and a little thin body, thin light hair and a sour expression. Her mother had been a great beauty and had cared only to go to parties and amuse herself with gay people. She had not wanted a little girl at all, and when Mary was born she handed her over to the care of an Ayah, who was made to understand that if she wished to please the Mem Sahib she must keep the child out of sight as much as possible. So when Mary was six years old she was as tyrannical and selfish a little pig as ever lived.',date:'Today',duration:'4 min',voice:'natural'}, {id:'p2',title:'The Tell-Tale Heart',genre:'Mystery',source:'Public domain · Edgar Allan Poe',text:'True!—nervous—very, very dreadfully nervous I had been and am; but why will you say that I am mad? The disease had sharpened my senses—not destroyed—not dulled them. Above all was the sense of hearing acute. I heard all things in the heaven and in the earth. I heard many things in hell. How, then, am I mad? Hearken! and observe how healthily—how calmly I can tell you the whole story.',date:'Yesterday',duration:'3 min',voice:'mysterious'},{id:'p3',title:'A Recipe for Wonder',genre:'Original',source:'An original kitchen story',text:'The kitchen smelled of cardamom and rain. Grandmother measured the flour with her eyes, never a cup, and told the dough a story while she kneaded. “Every recipe,” she said, “is a map back to someone who loved you.” Outside, the first snow of winter softened the rooftops. Inside, a small cake rose, golden as a lantern, and the whole house began to feel like a promise.',date:'Oct 24',duration:'2 min',voice:'gentle'}];
let stories=loadStories(),activeStory=null,utterance=null,playing=false,playerTimer=null,audioCtx=null,ambienceNodes=[],ocrModule=null,cameraStream=null;
function loadStories(){try{const s=JSON.parse(localStorage.getItem('storyverse-stories'));return Array.isArray(s)?s:initialStories}catch{return initialStories}}
function save(){try{localStorage.setItem('storyverse-stories',JSON.stringify(stories))}catch{toast('Storage is full. Remove a story before saving more.')}$('#libraryCount').textContent=String(stories.length).padStart(2,'0')}
function escapeHTML(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>el.classList.remove('show'),2800)}
function navigate(page){$$('.page').forEach(p=>p.classList.remove('active'));const el=$(`#${page}Page`);if(el)el.classList.add('active');$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.page===page));const names={home:'Discover',library:'My library',create:'Create a story',detail:'Experience'};$('#breadcrumb').innerHTML=`Your world of stories <span>／</span> ${names[page]||'Discover'}`;window.scrollTo({top:0,behavior:'smooth'});if(page==='library')renderLibrary()}
function card(s){return `<article class="story-card" data-open="${escapeHTML(s.id)}"><div class="story-cover" style="background-image:url('${s.image||covers[s.genre]||covers.Original}')"><span class="cover-badge">${escapeHTML(s.genre||'Original')}</span><span class="cover-duration">◷ ${escapeHTML(s.duration||duration(s.text))}</span></div><div class="story-info"><h3 class="story-title">${escapeHTML(s.title)}</h3><div class="story-meta"><span>✦</span> ${escapeHTML(s.source||'Your original story')}</div><div class="story-bottom"><span class="story-date">${escapeHTML(s.date||'Just now')}</span><button class="play-mini" data-play="${escapeHTML(s.id)}" aria-label="Play ${escapeHTML(s.title)}">▶</button></div></div></article>`}
function renderRecent(){const list=stories.slice(0,3);$('#recentGrid').innerHTML=list.map(card).join('');$('.heading-count').textContent=String(stories.length).padStart(2,'0');$('#libraryCount').textContent=String(stories.length).padStart(2,'0')}
function renderLibrary(){let query=($('#librarySearch')?.value||'').trim().toLowerCase(),genre=$('#libraryFilter')?.value||'all';let filtered=stories.filter(s=>(genre==='all'||s.genre===genre)&&(s.title.toLowerCase().includes(query)||(s.text||'').toLowerCase().includes(query)));$('#libraryGrid').innerHTML=filtered.map(card).join('');$('#emptyLibrary').classList.toggle('hidden',filtered.length>0)}
function duration(text){return `${Math.max(1,Math.ceil((text||'').split(/\s+/).length/145))} min`}
function detail(id){const s=stories.find(x=>x.id===id);if(!s)return;activeStory=s;navigate('detail');const image=s.image||covers[s.genre]||covers.Original;$('#detailContent').innerHTML=`<div class="detail-hero" style="background-image:url('${image}')"><div class="detail-hero-content"><div class="eyebrow">✦ &nbsp; ${escapeHTML(s.genre||'ORIGINAL')} EXPERIENCE</div><h1>${escapeHTML(s.title)}</h1><p>${escapeHTML(s.source||'Your original story')} &nbsp; · &nbsp; ${escapeHTML(s.duration||duration(s.text))}</p><div class="detail-actions"><button class="play-button" data-detail-play>▶ &nbsp; Listen to story</button><button data-toggle-ambience>♫ &nbsp; Soundscape <span id="ambienceState">off</span></button><button data-remove-story>Remove</button></div></div></div><div class="detail-body"><div class="detail-panel"><h3>The words behind the experience</h3><div class="excerpt">${escapeHTML(s.text||'No text saved.')}</div></div><div class="detail-panel"><h3>Experience settings</h3><div class="detail-side-info">Genre <b>${escapeHTML(s.genre||'Original')}</b><br> Narrator <b>${escapeHTML(s.voice||'Natural storyteller')}</b><br>Language <b>Browser voice language</b><br>Source <b>${escapeHTML(s.source||'Your original story')}</b></div><p style="font-size:8px;color:#777080;line-height:1.6;margin-top:12px">Narration uses your device's built-in speech voices. Soundscape is synthesized in your browser. This experience is not AI-generated.</p></div></div>`}
function showPlayer(s){closePlayer();if(!('speechSynthesis'in window)){toast('Speech narration is not available in this browser.');return}if(!s.text?.trim()){toast('This story has no text to narrate.');return}activeStory=s;const bar=document.createElement('div');bar.className='player-bar';bar.id='playerBar';bar.innerHTML=`<button class="player-play" id="playerPlay">Ⅱ</button><span class="player-title"><b>${escapeHTML(s.title)}</b><small>Device voice · ${escapeHTML(s.voice||'Natural')}</small></span><div class="player-track"><i id="playerProgress"></i></div><span class="player-time" id="playerWords">Ready</span><button id="playerClose" class="player-close">×</button>`;document.body.appendChild(bar);$('#playerPlay').onclick=()=>playing?pauseNarration():startNarration(s);$('#playerClose').onclick=closePlayer;startNarration(s)}
function startNarration(s){speechSynthesis.cancel();utterance=new SpeechSynthesisUtterance(s.text);const voiceMap={natural:1,dramatic:.86,gentle:.92,mysterious:.82};utterance.rate=voiceMap[s.voice]||1;utterance.pitch=s.voice==='mysterious'?.82:s.voice==='gentle'?1.08:1;const voices=speechSynthesis.getVoices();const preferred=voices.find(v=>v.lang===navigator.language)||voices.find(v=>v.lang.startsWith('en'));if(preferred)utterance.voice=preferred;utterance.onstart=()=>{playing=true;if($('#playerPlay'))$('#playerPlay').textContent='Ⅱ';$('#playerWords').textContent='Speaking'};utterance.onboundary=e=>{if($('#playerProgress')&&s.text.length)$('#playerProgress').style.width=`${Math.min(100,e.charIndex/s.text.length*100)}%`};utterance.onend=()=>{playing=false;if($('#playerPlay'))$('#playerPlay').textContent='▶';if($('#playerWords'))$('#playerWords').textContent='Finished';stopAmbience()};utterance.onerror=e=>{if(e.error!=='canceled')toast('Narration could not start. Try another browser voice.');playing=false};speechSynthesis.speak(utterance)}
function pauseNarration(){speechSynthesis.pause();playing=false;$('#playerPlay').textContent='▶'}function resumeNarration(){speechSynthesis.resume();playing=true;$('#playerPlay').textContent='Ⅱ'}
function closePlayer(){if('speechSynthesis'in window)speechSynthesis.cancel();playing=false;stopAmbience();$('#playerBar')?.remove()}
function toggleAmbience(){if(ambienceNodes.length){stopAmbience();toast('Soundscape paused');return}try{audioCtx ||= new (window.AudioContext||window.webkitAudioContext)();if(audioCtx.state==='suspended')audioCtx.resume();const master=audioCtx.createGain();master.gain.value=.035;master.connect(audioCtx.destination);[110,164.81,220].forEach((freq,i)=>{const osc=audioCtx.createOscillator(),gain=audioCtx.createGain();osc.type=i===1?'triangle':'sine';osc.frequency.value=freq;gain.gain.value=i===0?.45:.2;osc.connect(gain);gain.connect(master);osc.start();ambienceNodes.push(osc,gain)});ambienceNodes.push(master);if($('#ambienceState'))$('#ambienceState').textContent='on';toast('Ambient soundscape playing on this device')}catch{toast('Audio playback is not supported here.')}}
function stopAmbience(){ambienceNodes.forEach(n=>{try{if(n.stop)n.stop();if(n.disconnect)n.disconnect()}catch{}});ambienceNodes=[];if($('#ambienceState'))$('#ambienceState').textContent='off'}
function openModal(html){$('#modal').innerHTML=html;$('#modalBackdrop').classList.remove('hidden');$('#modalClose')?.addEventListener('click',closeModal);$('#modalBackdrop').onclick=e=>{if(e.target.id==='modalBackdrop')closeModal()}}
function closeModal(){stopCamera();$('#modalBackdrop').classList.add('hidden');$('#modal').innerHTML=''}
function openUpload(){const input=$('#fileInput');input.value='';input.click()}
async function onFile(file){if(!file)return;if(file.type==='text/plain'||file.name.endsWith('.md')){const text=await file.text();$('#storyText').value=text;$('#storyTitle').value=file.name.replace(/\.[^.]+$/,'');updateWordCount();navigate('create');toast('Text loaded. Review it and create your experience.');return}if(file.type==='application/pdf'||file.name.toLowerCase().endsWith('.pdf')){toast('PDF extraction is not available here. Please upload a page image or paste text.');return}if(!file.type.startsWith('image/')){toast('Choose an image or a plain-text file.');return}const image=URL.createObjectURL(file);openOCRImage(image)}
function openOCRImage(image){openModal(`<button class="modal-close" id="modalClose">×</button><h2>Read a page</h2><p>Text recognition runs in your browser with the open-source Tesseract.js OCR engine. Your photo is not uploaded to a Storyverse server.</p><img src="${image}" style="width:100%;max-height:240px;object-fit:contain;background:#09070f;border-radius:7px"/><div id="ocrStatus" class="license-note">OCR starts when you choose “Extract text”. First use downloads the OCR engine and language data from jsDelivr.</div><div class="modal-actions"><button class="primary-small" id="runOCR">Extract text</button><button class="primary-small" style="background:#201a28;border-color:#554363" id="cancelOCR">Cancel</button></div>`);$('#cancelOCR').onclick=closeModal;$('#runOCR').onclick=()=>runOCR(image)}
async function runOCR(image){const status=$('#ocrStatus'),button=$('#runOCR');button.disabled=true;button.textContent='Recognizing…';status.textContent='Loading OCR engine and English language data…';try{if(!ocrModule){const src='https://cdn.jsdelivr.net/npm/tesseract.js@5/dist/tesseract.min.js';await new Promise((resolve,reject)=>{const sc=document.createElement('script');sc.src=src;sc.onload=resolve;sc.onerror=()=>reject(Error('Could not load OCR engine. Check your internet connection.'));document.head.append(sc)});ocrModule=window.Tesseract}const result=await ocrModule.recognize(image,'eng',{logger:m=>{if(m.status)status.textContent=`${m.status}${m.progress?` · ${Math.round(m.progress*100)}%`:''}`}});const text=result.data.text.trim();if(!text)throw Error('No readable text found. Try a sharper, well-lit photo.');$('#storyText').value=text;if(!$('#storyTitle').value)$('#storyTitle').value='Scanned story';updateWordCount();closeModal();navigate('create');toast('Text extracted. Review and edit before creating.')}catch(e){status.textContent=e.message||'OCR failed. Try another image.';button.disabled=false;button.textContent='Try again'}}
function openCamera(){openModal(`<button class="modal-close" id="modalClose">×</button><h2>Capture a page</h2><p>Camera access stays in your browser. Point at printed text with even lighting.</p><video class="camera-video" id="cameraVideo" autoplay playsinline></video><canvas id="cameraCanvas" hidden></canvas><div class="license-note" id="cameraStatus">Allow camera access to take a picture. Requires HTTPS or localhost.</div><div class="modal-actions"><button class="primary-small" id="capturePhoto">Capture page</button><button class="primary-small" style="background:#201a28;border-color:#554363" id="cameraCancel">Cancel</button></div>`);$('#cameraCancel').onclick=closeModal;$('#capturePhoto').onclick=capturePage;startCamera()}
async function startCamera(){try{if(!navigator.mediaDevices?.getUserMedia)throw Error('Camera is unavailable. Try uploading an image instead.');cameraStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}},audio:false});$('#cameraVideo').srcObject=cameraStream;$('#cameraStatus').textContent='Camera ready. Frame the page and capture.'}catch(e){$('#cameraStatus').textContent=e.name==='NotAllowedError'?'Camera permission was denied. Allow access in browser settings or upload an image.':e.message}}
function stopCamera(){if(cameraStream){cameraStream.getTracks().forEach(t=>t.stop());cameraStream=null}}
function capturePage(){const video=$('#cameraVideo'),canvas=$('#cameraCanvas');if(!video?.videoWidth){toast('Camera is not ready yet.');return}canvas.width=video.videoWidth;canvas.height=video.videoHeight;canvas.getContext('2d').drawImage(video,0,0);canvas.toBlob(blob=>{stopCamera();closeModal();openOCRImage(URL.createObjectURL(blob))},'image/jpeg',.9)}
function updateWordCount(){const count=$('#storyText').value.trim().split(/\s+/).filter(Boolean).length;$('#wordCount').textContent=`${count} word${count===1?'':'s'}`}
function createStory(){const title=$('#storyTitle').value.trim(),text=$('#storyText').value.trim();if(!text){toast('Add some words first—write, paste, or scan a page.');$('#storyText').focus();return}if(!title){$('#storyTitle').focus();toast('Give your story a title.');return}const genre=$('#genreSelect').value,voice=$('#voiceSelect').value;const source='Original writing · saved on this device';const s={id:`story-${Date.now()}`,title,genre,source,text,date:'Just now',duration:duration(text),voice,image:covers[genre]||covers.Original};stories.unshift(s);save();renderRecent();$('#storyTitle').value='';$('#storyText').value='';updateWordCount();navigate('detail');detail(s.id);toast('Experience created. Play it with your device voice.');}
function removeStory(){if(!activeStory)return;stories=stories.filter(s=>s.id!==activeStory.id);save();renderRecent();navigate('library');toast('Story removed from this device.')}
function openUpgrade(){openModal(`<button class="modal-close" id="modalClose">×</button><div class="eyebrow">✦ &nbsp; STORYVERSE PLANS</div><h2>More room for wonder.</h2><p>This preview includes local story creation, browser narration and on-device storage. A paid plan, billing, AI generation, licensed voice catalog and cloud library are not connected in this demo.</p><div class="license-note"><b>Free preview</b><br>3 story experiences · Device voices · Local library<br><br><b>Premium concept</b><br>Expanded productions · Creator tools · Premium voice options<br><br>No subscription will be started or charged from this preview.</div><div class="modal-actions"><button class="primary-small" id="modalClose2">Got it</button></div>`);$('#modalClose2').onclick=closeModal}
// Global interactions
document.addEventListener('click',e=>{const goto=e.target.closest('[data-goto]');if(goto){navigate(goto.dataset.goto);return}const nav=e.target.closest('.nav-item');if(nav){navigate(nav.dataset.page);return}const op=e.target.closest('[data-open]');if(op){detail(op.dataset.open);return}const pl=e.target.closest('[data-play]');if(pl){e.stopPropagation();const s=stories.find(x=>x.id===pl.dataset.play);if(s)showPlayer(s);return}const genre=e.target.closest('[data-genre]');if(genre){navigate('library');$('#libraryFilter').value=genre.dataset.genre;renderLibrary();return}});
$('#scanBtn').onclick=openUpload;$('#uploadBtn').onclick=openUpload;$('#cameraBtn').onclick=openCamera;$('#writeBtn').onclick=()=>navigate('create');$('#libraryCreate').onclick=()=>navigate('create');$('#fileInput').onchange=e=>onFile(e.target.files[0]);$('#produceBtn').onclick=createStory;$('#storyText').oninput=updateWordCount;$('#librarySearch').oninput=renderLibrary;$('#libraryFilter').onchange=renderLibrary;$('#detailBack').onclick=()=>navigate('library');$('#detailContent').addEventListener('click',e=>{if(e.target.closest('[data-detail-play]'))showPlayer(activeStory);if(e.target.closest('[data-toggle-ambience]'))toggleAmbience();if(e.target.closest('[data-remove-story]'))removeStory()});$('#upgradeBtn').onclick=openUpgrade;$('#howItWorks').onclick=()=>openModal(`<button class="modal-close" id="modalClose">×</button><div class="eyebrow">A SIMPLE KIND OF MAGIC</div><h2>From page to play.</h2><p><b>01 · Bring your words.</b> Use the camera, choose a photo, upload a text file, or write your own story.</p><p><b>02 · Review your text.</b> Image OCR runs in your browser. Check the extraction and make any edits.</p><p><b>03 · Press play.</b> Your device's built-in voice narrates the story. A gentle synthesized tone bed is available as an optional soundscape.</p><div class="license-note">Only scan public-domain or licensed works, your own writing, and other content you are authorized to process. This preview does not use a cloud AI service.</div>`);$('#allGenres').onclick=()=>{navigate('library');$('#libraryFilter').value='all';renderLibrary()};$$('.creator-tab').forEach(b=>b.onclick=()=>{if(b.dataset.creator==='scan')openUpload();else $('#storyText').focus()});
$('#searchBtn').onclick=()=>{navigate('library');$('#librarySearch').focus()};$$('.genre-nav button').forEach(b=>b.addEventListener('click',()=>{navigate('library');$('#libraryFilter').value=b.dataset.genre;renderLibrary()}));
renderRecent();save();

