import { spawn } from 'node:child_process';
const child=spawn('/usr/bin/chromium',['--headless=new','--no-sandbox','--disable-gpu','--remote-debugging-port=9223','--user-data-dir=/tmp/storyverse-qa-profile','about:blank'],{stdio:'ignore'});
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
let targets;
for(let i=0;i<30;i++){try{targets=await (await fetch('http://127.0.0.1:9223/json')).json();break}catch{await sleep(300)}}
if(!targets){console.log('Chrome remote debugging unavailable');child.kill();process.exit(1)}
const page=targets.find(t=>t.type==='page');const ws=new WebSocket(page.webSocketDebuggerUrl);await new Promise((res,rej)=>{ws.onopen=res;ws.onerror=rej});let id=0;const pending=new Map();ws.onmessage=e=>{const m=JSON.parse(e.data);if(m.id&&pending.has(m.id)){pending.get(m.id)(m);pending.delete(m.id)}};
const call=(method,params={})=>new Promise(resolve=>{const n=++id;pending.set(n,resolve);ws.send(JSON.stringify({id:n,method,params}))});
await call('Page.enable');await call('Runtime.enable');await call('Page.navigate',{url:'http://localhost:3002'});await sleep(1000);
const evalJS=async expression=>(await call('Runtime.evaluate',{expression,awaitPromise:true,returnByValue:true})).result?.result?.value;
console.log('favicon',await evalJS(`fetch('/').then(async r=>({status:r.status, hasInlineFavicon:(await r.text()).includes('data:image/svg+xml')}))`));
console.log('voices',await evalJS(`({speech:'speechSynthesis' in window, voices:speechSynthesis.getVoices().map(v=>({name:v.name,lang:v.lang,local:v.localService}))})`));
console.log('ocr',await evalJS(`(async()=>{const c=document.createElement('canvas');c.width=1000;c.height=240;const x=c.getContext('2d');x.fillStyle='white';x.fillRect(0,0,1000,240);x.fillStyle='black';x.font='bold 64px Arial';x.fillText('STORYVERSE OCR TEST',30,145);const u=c.toDataURL('image/png');const t=await new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='https://cdn.jsdelivr.net/npm/tesseract.js@5/dist/tesseract.min.js';s.onload=resolve;s.onerror=()=>reject(Error('CDN unavailable'));document.head.append(s)});const r=await Tesseract.recognize(u,'eng');return r.data.text.trim()})()`));
console.log('narration',await evalJS(`new Promise(resolve=>{const u=new SpeechSynthesisUtterance('Storyverse narration test');u.onstart=()=>resolve('started');u.onerror=e=>resolve('error:'+e.error);speechSynthesis.speak(u);setTimeout(()=>resolve('timeout'),4000)})`));
ws.close();child.kill('SIGTERM');
