import { spawn } from 'node:child_process';
const child=spawn('/usr/bin/chromium',['--headless=new','--no-sandbox','--disable-gpu','--remote-debugging-port=9224','--user-data-dir=/tmp/storyverse-qa-click','about:blank'],{stdio:'ignore'});const sleep=ms=>new Promise(r=>setTimeout(r,ms));let ts;for(let i=0;i<30;i++){try{ts=await(await fetch('http://127.0.0.1:9224/json')).json();break}catch{await sleep(300)}}const ws=new WebSocket(ts.find(x=>x.type==='page').webSocketDebuggerUrl);await new Promise(r=>ws.onopen=r);let n=0;const p=new Map;ws.onmessage=e=>{const x=JSON.parse(e.data);if(x.id&&p.has(x.id)){p.get(x.id)(x);p.delete(x.id)}};const c=(method,params={})=>new Promise(r=>{let id=++n;p.set(id,r);ws.send(JSON.stringify({id,method,params}))});await c('Page.enable');await c('Runtime.enable');await c('Page.navigate',{url:'http://localhost:3002'});await sleep(800);let out=await c('Runtime.evaluate',{expression:`(()=>{const b=document.querySelector('[data-play]');const r=b.getBoundingClientRect();return {x:r.x+r.width/2,y:r.y+r.height/2,voices:speechSynthesis.getVoices().length}})()`,returnByValue:true});let q=out.result.result.value;await c('Input.dispatchMouseEvent',{type:'mousePressed',x:q.x,y:q.y,button:'left',clickCount:1});await c('Input.dispatchMouseEvent',{type:'mouseReleased',x:q.x,y:q.y,button:'left',clickCount:1});await sleep(300);console.log(await c('Runtime.evaluate',{expression:`new Promise(resolve=>{let u=new SpeechSynthesisUtterance('Test');u.onerror=e=>resolve(e.error);u.onstart=()=>resolve('started');speechSynthesis.speak(u);setTimeout(()=>resolve('pending'),2000)})`,awaitPromise:true,returnByValue:true}));ws.close();child.kill();
