Index: app.js
===================================================================
--- app.js
+++ app.js
@@ -12,9 +12,9 @@
 function renderLibrary(){let query=($('#librarySearch')?.value||'').trim().toLowerCase(),genre=$('#libraryFilter')?.value||'all';let filtered=stories.filter(s=>(genre==='all'||s.genre===genre)&&(s.title.toLowerCase().includes(query)||(s.text||'').toLowerCase().includes(query)));$('#libraryGrid').innerHTML=filtered.map(card).join('');$('#emptyLibrary').classList.toggle('hidden',filtered.length>0)}
 function duration(text){return `${Math.max(1,Math.ceil((text||'').split(/\s+/).length/145))} min`}
 function detail(id){const s=stories.find(x=>x.id===id);if(!s)return;activeStory=s;navigate('detail');const image=s.image||covers[s.genre]||covers.Original;$('#detailContent').innerHTML=`<div class="detail-hero" style="background-image:url('${image}')"><div class="detail-hero-content"><div class="eyebrow">✦ &nbsp; ${escapeHTML(s.genre||'ORIGINAL')} EXPERIENCE</div><h1>${escapeHTML(s.title)}</h1><p>${escapeHTML(s.source||'Your original story')} &nbsp; · &nbsp; ${escapeHTML(s.duration||duration(s.text))}</p><div class="detail-actions"><button class="play-button" data-detail-play>▶ &nbsp; Listen to story</button><button data-toggle-ambience>♫ &nbsp; Soundscape <span id="ambienceState">off</span></button><button data-remove-story>Remove</button></div></div></div><div class="detail-body"><div class="detail-panel"><h3>The words behind the experience</h3><div class="excerpt">${escapeHTML(s.text||'No text saved.')}</div></div><div class="detail-panel"><h3>Experience settings</h3><div class="detail-side-info">Genre <b>${escapeHTML(s.genre||'Original')}</b><br> Narrator <b>${escapeHTML(s.voice||'Natural storyteller')}</b><br>Language <b>Browser voice language</b><br>Source <b>${escapeHTML(s.source||'Your original story')}</b></div><p style="font-size:8px;color:#777080;line-height:1.6;margin-top:12px">Narration uses your device's built-in speech voices. Soundscape is synthesized in your browser. This experience is not AI-generated.</p></div></div>`}
 function showPlayer(s){closePlayer();if(!('speechSynthesis'in window)){toast('Speech narration is not available in this browser.');return}if(!s.text?.trim()){toast('This story has no text to narrate.');return}activeStory=s;const bar=document.createElement('div');bar.className='player-bar';bar.id='playerBar';bar.innerHTML=`<button class="player-play" id="playerPlay">Ⅱ</button><span class="player-title"><b>${escapeHTML(s.title)}</b><small>Device voice · ${escapeHTML(s.voice||'Natural')}</small></span><div class="player-track"><i id="playerProgress"></i></div><span class="player-time" id="playerWords">Ready</span><button id="playerClose" class="player-close">×</button>`;document.body.appendChild(bar);$('#playerPlay').onclick=()=>playing?pauseNarration():startNarration(s);$('#playerClose').onclick=closePlayer;startNarration(s)}
-function startNarration(s){speechSynthesis.cancel();utterance=new SpeechSynthesisUtterance(s.text);const voiceMap={natural:1,dramatic:.86,gentle:.92,mysterious:.82};utterance.rate=voiceMap[s.voice]||1;utterance.pitch=s.voice==='mysterious'?.82:s.voice==='gentle'?1.08:1;const voices=speechSynthesis.getVoices();const preferred=voices.find(v=>v.lang===navigator.language)||voices.find(v=>v.lang.startsWith('en'));if(preferred)utterance.voice=preferred;utterance.onstart=()=>{playing=true;if($('#playerPlay'))$('#playerPlay').textContent='Ⅱ';$('#playerWords').textContent='Speaking'};utterance.onboundary=e=>{if($('#playerProgress')&&s.text.length)$('#playerProgress').style.width=`${Math.min(100,e.charIndex/s.text.length*100)}%`};utterance.onend=()=>{playing=false;if($('#playerPlay'))$('#playerPlay').textContent='▶';if($('#playerWords'))$('#playerWords').textContent='Finished';stopAmbience()};utterance.onerror=e=>{if(e.error!=='canceled')toast('Narration could not start. Try another browser voice.');playing=false};speechSynthesis.speak(utterance)}
+function startNarration(s){speechSynthesis.cancel();utterance=new SpeechSynthesisUtterance(s.text);const voiceMap={natural:1,dramatic:.86,gentle:.92,mysterious:.82};utterance.rate=voiceMap[s.voice]||1;utterance.pitch=s.voice==='mysterious'?.82:s.voice==='gentle'?1.08:1;const voices=speechSynthesis.getVoices();const preferred=voices.find(v=>v.lang===navigator.language)||voices.find(v=>v.lang.startsWith('en'));if(preferred)utterance.voice=preferred;utterance.onstart=()=>{playing=true;if($('#playerPlay'))$('#playerPlay').textContent='Ⅱ';$('#playerWords').textContent='Speaking'};utterance.onboundary=e=>{if($('#playerProgress')&&s.text.length)$('#playerProgress').style.width=`${Math.min(100,e.charIndex/s.text.length*100)}%`};utterance.onend=()=>{playing=false;if($('#playerPlay'))$('#playerPlay').textContent='▶';if($('#playerWords'))$('#playerWords').textContent='Finished';stopAmbience()};utterance.onerror=e=>{playing=false;if($('#playerPlay'))$('#playerPlay').textContent='▶';if($('#playerWords'))$('#playerWords').textContent='Unavailable';const messages={'not-allowed':'Narration was blocked by this browser. Check audio playback permissions and try again.','voice-unavailable':'This device voice is unavailable. Try another browser or system voice.','synthesis-failed':'This browser could not start a device voice. Try another browser or enable a system speech voice.'};if(e.error!=='canceled')toast(messages[e.error]||'Narration could not start. Check that a device speech voice is available.')};speechSynthesis.speak(utterance)}
 function pauseNarration(){speechSynthesis.pause();playing=false;$('#playerPlay').textContent='▶'}function resumeNarration(){speechSynthesis.resume();playing=true;$('#playerPlay').textContent='Ⅱ'}
 function closePlayer(){if('speechSynthesis'in window)speechSynthesis.cancel();playing=false;stopAmbience();$('#playerBar')?.remove()}
 function toggleAmbience(){if(ambienceNodes.length){stopAmbience();toast('Soundscape paused');return}try{audioCtx ||= new (window.AudioContext||window.webkitAudioContext)();if(audioCtx.state==='suspended')audioCtx.resume();const master=audioCtx.createGain();master.gain.value=.035;master.connect(audioCtx.destination);[110,164.81,220].forEach((freq,i)=>{const osc=audioCtx.createOscillator(),gain=audioCtx.createGain();osc.type=i===1?'triangle':'sine';osc.frequency.value=freq;gain.gain.value=i===0?.45:.2;osc.connect(gain);gain.connect(master);osc.start();ambienceNodes.push(osc,gain)});ambienceNodes.push(master);if($('#ambienceState'))$('#ambienceState').textContent='on';toast('Ambient soundscape playing on this device')}catch{toast('Audio playback is not supported here.')}}
 function stopAmbience(){ambienceNodes.forEach(n=>{try{if(n.stop)n.stop();if(n.disconnect)n.disconnect()}catch{}});ambienceNodes=[];if($('#ambienceState'))$('#ambienceState').textContent='off'}

