node --check app.js && node --input-type=module <<'NODE'
import { spawn } from 'node:child_process';
const child=spawn('/usr/bin/chromium',['--headless=new','--no-sandbox','--disable-gpu','--remote-debugging-port=9225','--user-data-dir=/tmp/storyverse-final-qa','about:blank'],{stdio:'ignore'});const sleep=ms=>new Promise(r=>setTimeout(r,ms));let targets;for(let i=0;i<30;i++){try{targets=await(await fetch('http://127.0.0.1:9225/json')).json();break}catch{await sleep(250)}}if(!targets)throw Error('Chromium failed to start');const ws=new WebSocket(targets.find(t=>t.type==='page').webSocketDebuggerUrl);await new Promise(r=>ws.onopen=r);let id=0;const pending=new Map;ws.onmessage=e=>{const m=JSON.parse(e.data);if(m.id&&pending.has(m.id)){pending.get(m.id)(m);pending.delete(m.id)}};const call=(method,params={})=>new Promise(resolve=>{const i=++id;pending.set(i,resolve);ws.send(JSON.stringify({id:i,method,params}))});await call('Page.enable');await call('Runtime.enable');await call('Page.navigate',{url:'http://localhost:3002'});await sleep(800);const q=await call('Runtime.evaluate',{expression:`(()=>{const b=document.querySelector('[data-play]'),r=b.getBoundingClientRect();return{x:r.x+r.width/2,y:r.y+r.height/2,voices:speechSynthesis.getVoices().length,icon:document.querySelector('link[rel=icon]')?.href}})()`,returnByValue:true});const v=q.result.result.value;await call('Input.dispatchMouseEvent',{type:'mousePressed',x:v.x,y:v.y,button:'left',clickCount:1});await call('Input.dispatchMouseEvent',{type:'mouseReleased',x:v.x,y:v.y,button:'left',clickCount:1});await sleep(700);const result=await call('Runtime.evaluate',{expression:`({status:document.querySelector('#playerWords')?.textContent,toast:document.querySelector('#toast')?.textContent,icon:document.querySelector('link[rel=icon]')?.href})`,returnByValue:true});console.log(JSON.stringify({voices:v.voices,...result.result.result.value},null,2));ws.close();child.kill();
NODE

